#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
MIG="$ROOT/migrations/2026_09_06_fair_launch_action_execution.sql"
fail(){ echo "fair-launch action execution migration: $*" >&2; exit 1; }
[ -f "$MIG" ] || fail 'missing migration'
grep -Fq '@JC_FAIR_LAUNCH_MIGRATION_APPROVED' "$MIG" || fail 'missing fail-closed gate'
grep -Fq 'CREATE TABLE IF NOT EXISTS fair_launch_action_request' "$MIG" || fail 'request table is not restart safe'
grep -Fq 'CREATE TABLE IF NOT EXISTS fair_launch_preview' "$MIG" || fail 'one-time preview table missing'
grep -Fq 'KEY idx_fl_preview_digest(canonical_digest)' "$MIG" || fail 'preview digest audit index missing'
! grep -Fq 'UNIQUE KEY uk_fl_preview_digest(canonical_digest)' "$MIG" || fail 'identical preview payloads must remain independently issuable'
grep -Fq 'CREATE TABLE IF NOT EXISTS fair_launch_mfa_provider' "$MIG" || fail 'trusted MFA provider admission missing'
grep -Fq 'CREATE TABLE IF NOT EXISTS fair_launch_mfa_assertion' "$MIG" || fail 'single-use MFA assertion table missing'
grep -Fq "stage IN ('set_initiation','set_approval','action_initiation','action_approval','action_execution')" "$MIG" || fail 'MFA stage binding missing'
grep -Fq 'provider_id<>\x27test\x27' "$MIG" || grep -Fq "provider_id<>'test'" "$MIG" || fail 'test MFA provider rejection missing'
grep -Fq 'consumed_at DATETIME(6) NULL' "$MIG" || fail 'single-use consumption timestamp missing'
grep -Fq "preview is immutable and single-use" "$MIG" || fail 'preview mutation/replay guard missing'
grep -Fq "MFA assertion is immutable and single-use" "$MIG" || fail 'MFA assertion mutation/replay guard missing'
grep -Fq "preview audit is append-only" "$MIG" || fail 'preview delete guard missing'
grep -Fq "MFA assertion audit is append-only" "$MIG" || fail 'MFA assertion delete guard missing'
grep -Fq 'preview_id BIGINT UNSIGNED NOT NULL' "$MIG" || fail 'action request preview binding missing'
grep -Fq 'CREATE TABLE IF NOT EXISTS fair_launch_action_transition' "$MIG" || fail 'transition table is not restart safe'
grep -Fq 'admin_approval_id BIGINT UNSIGNED NULL' "$MIG" || fail 'approval link missing'
grep -Fq 'executor_admin_id BIGINT UNSIGNED NULL' "$MIG" || fail 'executor identity missing'
grep -Fq 'executor_mfa_evidence_ref' "$MIG" || fail 'executor MFA missing'
grep -Fq 'runtime_generation BIGINT UNSIGNED NOT NULL' "$MIG" || fail 'runtime generation missing'
grep -Fq 'source_registry_generation BIGINT UNSIGNED NOT NULL' "$MIG" || fail 'source generation missing'
grep -Fq 'UNIQUE KEY uk_fl_action_transition(action_request_id,sequence_no)' "$MIG" || fail 'append-only transition uniqueness missing'
for fk in fk_fl_action_initiator_admin fk_fl_action_approver_admin fk_fl_action_executor_admin fk_fl_action_transition_actor; do grep -Fq "$fk" "$MIG" || fail "admin identity FK missing: $fk"; done
grep -Fq 'initiator_admin_id>0' "$MIG" || fail 'positive admin ID guard missing'
grep -Fq "status IN ('approval_bound','approved') AND admin_approval_id IS NOT NULL AND approver_admin_id IS NOT NULL AND approver_mfa_evidence_ref IS NOT NULL" "$MIG" || fail 'approval work order and MFA at binding/approved missing'
grep -Fq "from_status='pending_approval' AND to_status IN ('approval_bound','expired','cancelled')" "$MIG" || fail 'approval binding transition missing'
grep -Fq "from_status='approval_bound' AND to_status IN ('approved','expired','cancelled')" "$MIG" || fail 'approval completion transition missing'
grep -Fq "from_status='approved' AND to_status IN ('execution_bound','expired','cancelled')" "$MIG" || fail 'executor binding transition missing'
grep -Fq "from_status='execution_bound' AND to_status IN ('executing','expired','cancelled')" "$MIG" || fail 'execution start transition missing'
grep -Fq 'action request status change requires latest valid transition' "$MIG" || fail 'request skip guard trigger missing'
grep -Fq 'fair_launch_action_transition is append-only' "$MIG" || fail 'append-only update/delete guard missing'
grep -Fq 'action request canonical identity is immutable' "$MIG" || fail 'canonical request mutation guard missing'
grep -Fq 'same-status action request mutation rejected' "$MIG" || fail 'same-status mutation guard missing'
grep -Fq "status IN ('pending_approval','approval_bound','approved','execution_bound','executing'" "$MIG" || fail 'explicit durable binding statuses missing'
grep -Fq 'approval transition requires prebound actor/MFA' "$MIG" || fail 'NULL-safe prebound approver actor/MFA binding missing'
grep -Fq 'execution transition requires prebound actor/MFA' "$MIG" || fail 'NULL-safe prebound executor actor/MFA binding missing'
grep -Fq 'NOT (NEW.actor_admin_id<=>v_approver)' "$MIG" || fail 'approval actor comparison is not NULL-safe'
grep -Fq 'NOT (NEW.mfa_evidence_ref<=>v_executor_mfa)' "$MIG" || fail 'executor MFA comparison is not NULL-safe'
grep -Fq 'NEW.external_observation_ref<=>OLD.external_observation_ref' "$MIG" || fail 'same-status execution link equality missing'
grep -Fq "OLD.status='pending_approval' AND OLD.admin_approval_id IS NULL AND NEW.admin_approval_id IS NOT NULL" "$MIG" || fail 'durable approval work-order link missing'
grep -Fq "OLD.status='pending_approval' AND NEW.status='approval_bound'" "$MIG" || fail 'durable approval binding update missing'
grep -Fq "OLD.status='approved' AND NEW.status='execution_bound'" "$MIG" || fail 'durable executor binding update missing'
grep -Fq 'terminal transition actor is not a recorded stage identity' "$MIG" || fail 'cancel/expire actor binding missing'
grep -Fq 'fair_launch_action_request is append-only' "$MIG" || fail 'request delete guard missing'
# Static adversarial fixtures: spoofed actors must be rejected and one-link enrichment
# must preserve all unrelated links through NULL-safe equality.
grep -Fq "NEW.from_status='approval_bound' AND NEW.to_status='approved' AND (v_approver IS NULL OR v_approver_mfa IS NULL OR v_approver_mfa_at IS NULL" "$MIG" || fail 'NULL bypass remains in approval transition'
grep -Fq "NEW.from_status='execution_bound' AND NEW.to_status='executing' AND (v_executor IS NULL OR v_executor_mfa IS NULL OR v_executor_mfa_at IS NULL" "$MIG" || fail 'NULL bypass remains in execution transition'
grep -Fq "OLD.submission_id IS NULL AND NEW.submission_id IS NOT NULL AND NEW.timelock_operation_row_id<=>OLD.timelock_operation_row_id AND NEW.safe_tx_id<=>OLD.safe_tx_id AND NEW.external_observation_ref<=>OLD.external_observation_ref" "$MIG" || fail 'link-smuggling guard missing'
grep -Fq '2026_09_06_fair_launch_action_execution.sql' "$ROOT/migrations/FAIR_LAUNCH_SHA256SUMS" || fail '09_06 checksum binding missing'
grep -Fq 'real MySQL 8' "$ROOT/migrations/verify/FAIR_LAUNCH_MYSQL8_SCHEMA_SNAPSHOT_SPEC.md" || fail '09_06 MySQL schema snapshot contract missing'
grep -Fq '2026_09_06_fair_launch_action_execution.sql' "$ROOT/scripts/fair-launch/schema-snapshot.js" || fail '09_06 snapshot phase binding missing'
grep -Fq 'database_migration_entrypoint=available_controlled' "$ROOT/scripts/cmd/migrate.sh" || fail 'controlled migration entrypoint missing'
grep -Fq 'migration_repository_checksum_mismatch' "$ROOT/scripts/cmd/migrate.sh" || fail 'migration checksum boundary missing'
! grep -Eqi '\b(GRANT|REVOKE|DROP TABLE|TRUNCATE)\b' "$MIG" || fail 'destructive/privilege DDL found'
echo 'Fair Launch action execution migration static validation: PASS'
